export async function updateOrganization(
  actor: Actor,
  input: UpdateOrganizationInput,
): Promise<Organization> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "org:update", orgResource(input.orgId));

  const updated = await orgRepo.updateOrg(input.orgId, input);

  // Settings changes are audited directly: the event bus has no
  // `organization.updated` key, and inventing one would widen the contract.
  await record(input.orgId, "organization.updated", {
    actorId: actor.userId,
    subjectKind: "organization",
    subjectId: updated.id,
    projectId: null,
    summary: `${updated.name} settings updated`,
  });

  return updated;
}

export async function renameOrganizationSlug(
  actor: Actor,
  input: RenameOrganizationSlugInput,
): Promise<Organization> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "org:update", orgResource(input.orgId));
  assertValidSlug(input.slug);

  const current = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );
  if (current.slug === input.slug) return current;

  const taken = await orgRepo.listTakenOrgSlugs(input.slug);
  if (taken.includes(input.slug)) {
    throw new InvalidSlugError(input.slug, "is unavailable");
  }

  let updated: Organization;
  try {
    updated = await orgRepo.renameOrgSlug(input.orgId, input.slug);
  } catch (error) {
    if (error instanceof Error && error.message === "Slug is unavailable") {
      throw new InvalidSlugError(input.slug, "is unavailable");
    }
    throw error;
  }

  await emit("organization.slug_changed", {
    ...envelope(input.orgId, actor.userId),
    from: current.slug,
    to: updated.slug,
  });
  await record(input.orgId, "organization.slug_changed", {
    actorId: actor.userId,
    subjectKind: "organization",
    subjectId: updated.id,
    projectId: null,
    summary: `Workspace URL changed from ${current.slug} to ${updated.slug}`,
    metadata: { from: current.slug, to: updated.slug },
  });
  return updated;
}

